    n = instance["n"]; edges = instance["edges"]; k = instance["k"]
    # Edge cases:
    if k < 0:
        return {"num_vars":0, "clauses":[[]]}
    if n == 0:
        return {"num_vars":0, "clauses":[]}
    if k >= n:
        return {"num_vars":0, "clauses":[]}
    # Build adjacency list
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    # variable numbering: first n variables are x_i (1-indexed for SAT)
    # Then assignment variables a_{i,s} where s from 1..k.
    var_idx = {}
    # assign numbers
    cur = 1
    x_vars = []
    for i in range(n):
        x_vars.append(cur)
        var_idx[('x', i)] = cur
        cur += 1
    a_vars = {}
    for i in range(n):
        for s in range(1, k+1):
            a_vars[(i,s)] = cur
            cur += 1
    num_vars = cur - 1
    clauses = []
    # domination clauses
    for v in range(n):
        lits = [x_vars[v]]
        for u in adj[v]:
            lits.append(x_vars[u])
        # clause must have at least one true: OR of those literals
        clauses.append(lits)
    # size constraint clauses
    # if k == 0, then no x_i can be true, so we need clauses forcing each x_i false: [-x_i]
    if k == 0:
        for i in range(n):
            clauses.append([-x_vars[i]])
        # also domination constraints already ensure each vertex must be in D (since no neighbors can dominate). That's fine.
    else:
        # x_i -> at least one a_{i,s}
        for i in range(n):
            clause = [-x_vars[i]] + [a_vars[(i,s)] for s in range(1, k+1)]
            clauses.append(clause)
        # a_{i,s} -> x_i
        for i in range(n):
            for s in range(1, k+1):
                clauses.append([-a_vars[(i,s)], x_vars[i]])
        # at most one vertex per slot: for each slot s, for each i<j
        for s in range(1, k+1):
            for i in range(n):
                for j in range(i+1, n):
                    clauses.append([-a_vars[(i,s)], -a_vars[(j,s)]])
    return {"num_vars": num_vars, "clauses": clauses}

